dna = (
    ""
)

print("Nucleotide Sequence Analyzer")
print("Sequence length:", len(dna))

a_count = 0
t_count = 0
g_count = 0
c_count = 0

for base in dna:
    if base == "A":
        a_count += 1
    elif base == "T":
        t_count += 1
    elif base == "G":
        g_count += 1
    elif base == "C":
        c_count += 1

print("A:", a_count)
print("T:", t_count)
print("G:", g_count)
print("C:", c_count)

gc_content = ((g_count + c_count) / len(dna)) * 100

print("GC content:", round(gc_content, 2), "%")

print("First 10 bases:", dna[:10])
print("Last 10 bases:", dna[-10:])